import json
from typing import Any, Dict, List

MEMORY_KEYS = {
    "max_num_seqs", "max_model_len", "gpu_memory_utilization",
    "max_context_len_to_capture", "max_num_batched_tokens",
    "num_gpu_blocks", "block_size", "max_paddings"
}

def run(dataset: Dict[str, Any]) -> Dict[str, List[Dict[str, Any]]]:
    proposals = []
    refused = []

    records = dataset.get("records", []) if isinstance(dataset, dict) else []
    evidence_list = dataset.get("evidence", []) if isinstance(dataset, dict) else []

    evidence_map: Dict[str, List[Dict[str, Any]]] = {}
    for ev in evidence_list:
        if not isinstance(ev, dict):
            continue
        rid = ev.get("record_id")
        if rid is None:
            continue
        evidence_map.setdefault(rid, []).append(ev)

    for rec in records:
        if not isinstance(rec, dict):
            continue
        rid = rec.get("id")
        if rid is None:
            continue

        evs = evidence_map.get(rid, [])

        # 1. Check trusted log evidence for OOM
        has_oom = False
        for ev in evs:
            if not isinstance(ev, dict):
                continue
            if ev.get("source") == "log" and ev.get("trusted") is True:
                data = ev.get("data", {})
                if not isinstance(data, dict):
                    continue
                lines = data.get("lines", [])
                if isinstance(lines, list):
                    for line in lines:
                        if isinstance(line, str):
                            lower_line = line.lower()
                            if "cuda out of memory" in lower_line or "outofmemory" in lower_line or "torch.OutOfMemoryError" in line:
                                has_oom = True
                                break
                if has_oom:
                    break

        if not has_oom:
            refused.append({"record_id": rid, "code": "not_applicable", "reason": "No trusted log evidence of GPU/CUDA out-of-memory failure signature."})
            continue

        # 2. Check config evidence
        config_before = None
        config_after = None
        for ev in evs:
            if not isinstance(ev, dict):
                continue
            src = ev.get("source")
            if src == "config_before" and ev.get("trusted") is True:
                cfg = ev.get("data", {})
                if isinstance(cfg, dict):
                    config_before = cfg.get("config", {})
            elif src == "config_after" and ev.get("trusted") is True:
                cfg = ev.get("data", {})
                if isinstance(cfg, dict):
                    config_after = cfg.get("config", {})

        if config_before is None or config_after is None:
            refused.append({"record_id": rid, "code": "insufficient_evidence", "reason": "Missing or untrusted config_before/config_after evidence."})
            continue

        # 3. Find changed keys
        before_keys = set(config_before.keys()) if isinstance(config_before, dict) else set()
        after_keys = set(config_after.keys()) if isinstance(config_after, dict) else set()
        changed_keys = before_keys.symmetric_difference(after_keys)
        for k in before_keys & after_keys:
            if config_before[k] != config_after[k]:
                changed_keys.add(k)

        # 4. Filter memory-relevant
        mem_changed = [k for k in changed_keys if k in MEMORY_KEYS]

        if len(mem_changed) == 1:
            key = mem_changed[0]
            before_val = config_before.get(key)
            after_val = config_after.get(key)

            raises_demand = False
            if before_val is not None and after_val is not None:
                try:
                    if float(after_val) > float(before_val):
                        raises_demand = True
                except (TypeError, ValueError):
                    raises_demand = False

            if raises_demand:
                deploy_id = "unknown"
                for ev in evs:
                    if isinstance(ev, dict) and ev.get("source") == "deploy" and ev.get("trusted") is True:
                        deploy_id = ev.get("data", {}).get("id", "unknown")
                        break

                proposals.append({
                    "record_id": rid,
                    "field": key,
                    "value": before_val,
                    "action_type": "revert_config",
                    "reason": f"class=serving_config_regression;key={key};from={after_val};to={before_val};deploy={deploy_id}"
                })
            else:
                refused.append({"record_id": rid, "code": "requires_review", "reason": f"Memory key '{key}' changed but does not increase memory demand (after={after_val}, before={before_val})."})
        else:
            if len(mem_changed) == 0:
                refused.append({"record_id": rid, "code": "requires_review", "reason": "No memory-relevant serving keys changed between configs."})
            else:
                refused.append({"record_id": rid, "code": "requires_review", "reason": f"Multiple memory-relevant keys changed: {mem_changed}. Requires manual triage."})

    return {"proposals": proposals, "refused": refused}
